String _uniqueAiinProviderName(
  ProviderRegistry registry,
  String identity,
  String baseUrl,
) {
  var name = identity;
  var suffix = 2;
  while (registry.providers.any(
    (p) => p.name == name && p.baseUrl == baseUrl,
  )) {
    name = '$identity-${suffix++}';
  }
  return name;
}

