  KeychainStore? keychainStore,
) async {
  var persisted = false;
  final keychain = keychainStore ?? const KeychainStore();
  if (await keychain.isAvailable()) {
    persisted = await keychain.set(keyName, key);
  }
  if (!persisted) {
    await sessionKeysStore?.set(keyName, key);
  }
}

